html:
{#- Interview Shortlist, laid out like Luuka's shortlist sheet: the position's
    applicants invited to interview, each written out from their Bio-Data. -#}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro lines(value) -%}{{ v(value) | replace("\n", "<br>") }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set position = doc.designation or frappe.db.get_value("Job Opening", doc.job_opening, "job_title") or doc.job_opening -%}
<style>
	.lpl-shortlist { font-family: Arial, Helvetica, sans-serif; font-size: 10px; color: #000; }
	.lpl-shortlist table { width: 100%; border-collapse: collapse; }
	.lpl-shortlist tr { page-break-inside: avoid; }
	.lpl-shortlist th, .lpl-shortlist td { border: 1px solid #555; padding: 4px 6px; vertical-align: top; text-align: left; }
	.lpl-shortlist th { font-weight: bold; background: #f2f2f2; }
	.lpl-shortlist .brand { border: 0; margin-bottom: 6px; }
	.lpl-shortlist .brand td { border: 0; padding: 0; vertical-align: middle; }
	.lpl-shortlist h3 { text-align: center; font-size: 13px; font-weight: bold; margin: 4px 0 10px; }
	.lpl-shortlist .no { width: 4%; text-align: center; }
</style>
<div class="lpl-shortlist">
	<table class="brand">
		<tr>
			<td style="width: 20%">{% if logo %}<img src="{{ logo }}" style="max-height: 44px">{% endif %}</td>
			<td style="text-align: right">LUUKA PLASTICS LIMITED<br>
				{{ frappe.utils.format_date(doc.shortlist_date) if doc.shortlist_date else "" }}</td>
		</tr>
	</table>
	<h3>{{ v(position) | upper }} SHORTLIST</h3>
	<table>
		<tr>
			<th class="no">NO.</th>
			<th style="width: 22%">NAME</th>
			<th style="width: 25%">EDUCATION QUALIFICATION</th>
			<th style="width: 27%">WORK EXPERIENCE</th>
			<th>CERTIFICATIONS AND LICENSES</th>
		</tr>
		{%- for row in doc.candidates %}
		<tr>
			<td class="no">{{ loop.index }}</td>
			<td>{{ v([row.applicant_name, row.phone_number, row.email_id] | select | join(", ")) }}</td>
			<td>{{ lines(row.education) }}</td>
			<td>{{ lines(row.work_experience) }}</td>
			<td>{{ lines(row.certifications) }}</td>
		</tr>
		{%- endfor %}
	</table>
</div>
